dry = ENV["DRY_RUN"] == "1"
changes = 0
ActiveRecord::Base.transaction do
  edits.group_by { |slug, _, _, _| slug }.each do |slug, list|
    record = AuditCase.find_by(slug: slug)
    next unless record

    attrs = {}
    list.each do |_, column, old, new|
      text = attrs[column] || record.public_send(column).to_s
      next if text.include?(new) && !text.include?(old)
      raise "[g13-goe-lesson] fingerprint missing: #{slug}/#{column}" unless text.scan(old).size == 1

      attrs[column] = text.sub(old) { new }
      changes += 1
    end
    record.update_columns(attrs.merge(updated_at: Time.current)) if attrs.any? && !dry
  end
end
puts "  [g13-goe-lesson] #{"DRY_RUN " if dry}changes=#{changes}"
